mapper.select:
SELECT r.id, r.vehicle_id, v.vin, a.dealer_id, d.dealer_name, r.stage_status, r.drosstech_status, r.upload_date, r.registration_date, r.customer_region, r.remark8, r.confirmed_by, r.confirmed_at FROM t_veh_registration r INNER JOIN t_vehicle v ON v.id = r.vehicle_id AND v.deleted = 0 LEFT JOIN t_veh_allocation a ON a.vehicle_id = r.vehicle_id AND a.deleted = 0 LEFT JOIN t_md_dealer d ON d.id = a.dealer_id AND d.deleted = 0 WHERE r.deleted = 0
AND v.vin LIKE CONCAT('%', #{query.vin}, '%')
AND a.dealer_id = #{query.dealerId}
AND r.stage_status = #{query.stageStatus}
ORDER BY r.id DESC
